import {SessionPresentation,clamp} from './models.js';
import {esc} from './workspace.js';
import {normalizeOperationalTerminalState,operationalInputAvailability,operationalStateData} from './operational/presentation.js';
export const RUNTIME_ADAPTER_CONTRACT=Object.freeze({id:'RuntimeAdapter',version:'1.0.0',compatibility:'SEMVER'});
/** Rendering adapter consumes session output; it never parses or executes input. */
export class DomTerminalRendererAdapter {
  constructor(){this.id='DomTerminalRendererAdapter';}
  render(session,provider){const state=normalizeOperationalTerminalState(provider,session);return `<div class="terminal-state"><span class="state-token" data-state="${esc(operationalStateData(state.state))}" role="status" aria-live="polite">${esc(state.label)}</span>${state.detail?`<span class="runtime-detail">${esc(state.detail)}</span>`:''}</div><div class="terminal-output" role="log" aria-label="${esc(provider.label)} output ${esc(session.id)}" tabindex="0" dir="ltr" data-terminal-state="${esc(state.state)}">${session.lines.map(line=>`<div><span class="terminal-command">${esc(provider.prompt(session))} ${esc(line.command)}</span><pre>${esc(line.output)}</pre></div>`).join('')||`<p>${esc(provider.help)}</p>`}</div>`;}
}
/** Presentation never implements command interpretation. Provider input is adapter-owned. */
export class OperationalView {
  constructor(host,provider,workspace,onChange,renderer=new DomTerminalRendererAdapter()){this.host=host;this.provider=provider;this.providerDescriptor=provider.descriptor();if(this.providerDescriptor.contract?.id!==RUNTIME_ADAPTER_CONTRACT.id)throw Error('INVALID_RUNTIME_ADAPTER_CONTRACT');this.workspace=workspace;this.onChange=onChange;this.renderer=renderer;this.model=new SessionPresentation();this.invocation=0;this.returnFocus=null;this.lastError='';this.readOnly=false;for(const action of ['dock','float','split','minimize','close','tab-left','tab-right','geometry'])workspace.commands.register('session.'+action,'SessionPresentation',action,p=>this.action(action),()=>this.model.sessions.length>0||'Open a runtime session first');workspace.commands.register('session.select','SessionPresentation','Select session',p=>{this.model.select(p.id);this.render({focusSession:p.id})},p=>this.model.sessions.some(s=>s.id===p.id)||'Choose a session');workspace.commands.register('session.detach','SessionPresentation','Close visible tab',p=>{this.model.detach(p.id);this.render({focusSession:this.model.active});return {sessionId:p.id,preservedBy:this.providerDescriptor.id}},p=>this.model.sessions.some(s=>s.id===p.id)||'Choose a visible session tab');workspace.commands.register('runtime.input',this.providerDescriptor.commandOwner,'Send runtime input',p=>this.provider.input(p.sessionId,p.command,p.invocationId),p=>this.inputAvailability(p.sessionId).enabled||this.inputAvailability(p.sessionId).reason);this.render();}
  inputAvailability(sessionId){if(this.readOnly)return {enabled:false,reason:'Recorded Results are read only.',state:normalizeOperationalTerminalState(this.provider,this.provider.session(sessionId))};return operationalInputAvailability(this.provider,this.provider.session(sessionId));}
  open(device){if(this.host.hidden||!this.model.sessions.length){const active=document.activeElement;this.returnFocus=active&&active!==document.body?active:null;}const session=this.provider.open(device);this.model.attach(session);this.lastError='';this.render({focusInput:session.id});return this.model.active;}
  _focus(selector){queueMicrotask(()=>this.host.querySelector(selector)?.focus());}
  render({focusSession=null,focusInput=null}={}){const m=this.model;this.providerDescriptor=this.provider.descriptor();this.host.dataset.mode=m.mode;this.host.dataset.runtimeTruth=this.providerDescriptor.runtimeTruth||this.providerDescriptor.id;this.host.hidden=!m.sessions.length;this.host.className='operational-host';if(m.mode==='float'){Object.assign(this.host.style,{left:`${m.geometry.x}px`,top:`${m.geometry.y}px`,width:`${m.geometry.width}px`,height:`${m.geometry.height}px`})}else this.host.removeAttribute('style');
    const providerState=this.provider.connected===false?'Unavailable':'Available';
    this.host.innerHTML=`<header class="operational-head"><strong>${esc(this.providerDescriptor.label)}</strong><span class="state-token" data-state="${this.provider.connected===false?'error':'completed'}" role="status" data-provider-state>${providerState}</span><button class="btn" data-ops="dock" aria-pressed="${m.mode==='dock'}">Dock</button><button class="btn" data-ops="float" aria-pressed="${m.mode==='float'}">Float</button><button class="btn" data-ops="split" aria-pressed="${m.mode==='split'}">Split</button><button class="btn" data-ops="geometry">Move / Resize</button><button class="btn" data-ops="minimize">${m.minimized?'Restore':'Minimize'}</button><button class="btn" data-ops="close" aria-label="Close session presentation">×</button></header><div role="tablist" class="session-tabs" aria-label="Session tabs">${m.sessions.map(s=>`<span class="session-tab"><button class="btn" role="tab" tabindex="${m.active===s.id?'0':'-1'}" aria-selected="${m.active===s.id}" data-session="${esc(s.id)}">${esc(s.deviceId)} · ${esc(s.id)}</button><button class="btn" data-detach-session="${esc(s.id)}" aria-label="Close visible tab ${esc(s.deviceId)}">×</button></span>`).join('')}<button class="btn" data-ops="tab-left" aria-label="Move selected tab left">←</button><button class="btn" data-ops="tab-right" aria-label="Move selected tab right">→</button></div>${this.lastError?`<p class="state-token" data-state="error" role="alert" data-runtime-error>${esc(this.lastError)}</p>`:''}<div class="session-body" ${m.minimized?'hidden':''}>${(m.mode==='split'?m.sessions.slice(0,2):m.sessions.filter(s=>s.id===m.active)).map(s=>{const availability=this.inputAvailability(s.id);return `<section class="terminal-session" data-session-panel="${esc(s.id)}">${this.renderer.render(s,this.providerDescriptor)}<form data-terminal-form="${esc(s.id)}"><label>${esc(this.providerDescriptor.inputLabel)} <input name="command" aria-label="Command for ${esc(s.deviceId)}" autocomplete="off" spellcheck="false" dir="ltr" ${availability.enabled?'':'disabled'}></label><button class="btn" type="submit" ${availability.enabled?'':'disabled'}>Run</button>${availability.enabled?'':`<span role="status" data-input-unavailable>${esc(availability.reason)}</span>`}</form></section>`}).join('')}</div><div class="window-resize" role="separator" tabindex="0" aria-label="Resize operational window"></div>`;
    this.host.querySelectorAll('[data-ops]').forEach(b=>b.onclick=()=>this.workspace.api.Commands.execute('session.'+b.dataset.ops));this.host.querySelectorAll('[data-detach-session]').forEach(b=>b.onclick=()=>this.workspace.api.Commands.execute('session.detach',{id:b.dataset.detachSession}));this.host.querySelectorAll('[data-session]').forEach(b=>{b.onclick=()=>this.workspace.api.Commands.execute('session.select',{id:b.dataset.session});b.onkeydown=e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();let i=m.sessions.findIndex(s=>s.id===b.dataset.session);i=e.key==='Home'?0:e.key==='End'?m.sessions.length-1:(i+(e.key==='ArrowRight'?1:-1)+m.sessions.length)%m.sessions.length;m.select(m.sessions[i].id);this.render({focusSession:m.active})}}});
    this.host.querySelectorAll('form').forEach(form=>{form.onsubmit=e=>{e.preventDefault();const input=form.elements.command,text=String(input.value??''),availability=this.inputAvailability(form.dataset.terminalForm);if(!availability.enabled){this.lastError=availability.reason;this.render({focusSession:form.dataset.terminalForm});return}if(!text.trim())return;try{this.workspace.api.Commands.execute('runtime.input',{sessionId:form.dataset.terminalForm,command:text,invocationId:`ui-${++this.invocation}`});this.lastError='';this.onChange();this.render({focusInput:form.dataset.terminalForm})}catch(err){this.lastError=String(err?.message||err);this.workspace.status(this.lastError,'error');this.render({focusSession:form.dataset.terminalForm})}};form.elements.command.onkeydown=e=>{if(e.key==='ArrowUp'){e.preventDefault();const s=this.provider.session(form.dataset.terminalForm);form.elements.command.value=s?.history.at(-1)||''}}});
    const resize=this.host.querySelector('.window-resize');resize.onkeydown=e=>{if(e.key.startsWith('Arrow')){e.preventDefault();m.geometry.width=clamp(m.geometry.width+(e.key==='ArrowRight'?20:e.key==='ArrowLeft'?-20:0),320,innerWidth);m.geometry.height=clamp(m.geometry.height+(e.key==='ArrowDown'?20:e.key==='ArrowUp'?-20:0),200,innerHeight);this.render()}};
    if(focusSession)this._focus(`[data-session="${focusSession}"]`);if(focusInput)this._focus(`[data-terminal-form="${focusInput}"] input`);
  }
  action(a){const m=this.model;if(['dock','float','split'].includes(a)){if(a==='split'&&m.sessions.length<2){this.workspace.status('Open a second runtime session before split view.','error');return}m.present(a)}if(a==='minimize')m.minimized=!m.minimized;if(a==='close'){this.host.hidden=true;this.workspace.status('Session presentation closed; runtime sessions are retained by the provider.');const target=this.returnFocus;if(target?.isConnected)queueMicrotask(()=>target.focus());return}if(a==='tab-left'||a==='tab-right')m.reorder(m.active,a==='tab-left'?-1:1);if(a==='geometry'){this.workspace.dialog('Window position and size',`<form id="geometryForm">${Object.entries(m.geometry).map(([k,v])=>`<label>${k}<input name="${k}" type="number" value="${v}"></label>`).join('')}<button class="btn">Apply</button></form>`,{onMount:bd=>bd.querySelector('form').onsubmit=e=>{e.preventDefault();const f=e.target;for(const k of Object.keys(m.geometry))m.geometry[k]=Number(f.elements[k].value);m.geometry.x=clamp(m.geometry.x,0,innerWidth-100);m.geometry.y=clamp(m.geometry.y,0,innerHeight-80);m.geometry.width=clamp(m.geometry.width,320,innerWidth);m.geometry.height=clamp(m.geometry.height,200,innerHeight);this.workspace.closeDialog();this.render()}});return}this.render({focusSession:m.active});}
}
